  const pass = authService.authenticateUser('admin', '123456');
  const fail = authService.authenticateUser('admin', 'bad-password');

  return {
    pass: Boolean(pass),
    fail: !fail,
  };
}

module.exports = { registerLoginRoutes, renderLoginPage, authenticateUser, runLoginTests };

